    var $ = window.jQuery;
    if (!$ || !$.fn.select2) {
        return;
    }

    $('.uclass-select2').each(function () {
        var $el = $(this);
        if ($el.hasClass('select2-hidden-accessible')) {
            $el.select2('destroy');
        }

        $el.select2({
            language: 'vi',
            width: '220px',
            placeholder: '--Chọn--',
            allowClear: true,
            dropdownAutoWidth: false
        });
    });
}

