private bool ConvertDocFolderToPdf(string strFolderPath)
{
    string strSofficeExe = WebGlobal.PhysicalDirectory_sofficeExePath;
    if (string.IsNullOrEmpty(strSofficeExe) || !File.Exists(strSofficeExe))
    {
        MsgBox.ShowError("Không tìm thấy LibreOffice để chuyển PDF.");
        return false;
    }

    string[] arrDocFiles = Directory.GetFiles(strFolderPath, "*.doc");
    if (arrDocFiles.Length == 0)
        return false;

    StringBuilder sbArgs = new StringBuilder();
    sbArgs.Append("--headless --nologo --norestore --convert-to pdf --outdir \"");
    sbArgs.Append(strFolderPath);
    sbArgs.Append("\"");
    for (int i = 0; i < arrDocFiles.Length; i++)
    {
        sbArgs.Append(" \"");
        sbArgs.Append(arrDocFiles[i]);
        sbArgs.Append("\"");
    }

    ProcessStartInfo objStartInfo = new ProcessStartInfo();
    objStartInfo.FileName = strSofficeExe;
    objStartInfo.Arguments = sbArgs.ToString();
    objStartInfo.CreateNoWindow = true;
    objStartInfo.UseShellExecute = false;
    objStartInfo.WorkingDirectory = strFolderPath;

    using (Process objProcess = Process.Start(objStartInfo))
    {
        objProcess.WaitForExit(600000);
        if (objProcess.ExitCode != 0)
            return false;
    }

    for (int i = 0; i < arrDocFiles.Length; i++)
    {
        string strPdfPath = Path.ChangeExtension(arrDocFiles[i], ".pdf");
        if (!File.Exists(strPdfPath))
            return false;
    }

    return true;
}

